// src/actions/characterActions.ts
import type { Room } from 'trystero/torrent';
import type { Character, GameState } from '../types/game';
import { selfId } from 'trystero';

// Action types must be 12 bytes or less for Trystero
export const CharacterActions = {
  CREATE: 'charCreate',
  UPDATE: 'charUpdate',
  DELETE: 'charDelete',
  SELECT: 'charSelect'
} as const;

interface CharacterCreatePayload {
  character: Omit<Character, 'id'>;
  playerId: string;
}

interface CharacterUpdatePayload {
  id: string;
  updates: Partial<Character>;
  playerId: string;
}

interface CharacterDeletePayload {
  id: string;
  playerId: string;
}

interface CharacterSelectPayload {
  characterId: string;
  playerId: string;
}

export function setupCharacterActions(
  room: Room,
  gameState: GameState,
  onGameStateChange: (newState: GameState) => void,
  isRoomCreator: boolean
) {
  // Setup action handlers
  const [sendCharCreate, getCharCreate] = room.makeAction<CharacterCreatePayload>(CharacterActions.CREATE);
  const [sendCharUpdate, getCharUpdate] = room.makeAction<CharacterUpdatePayload>(CharacterActions.UPDATE);
  const [sendCharDelete, getCharDelete] = room.makeAction<CharacterDeletePayload>(CharacterActions.DELETE);
  const [sendCharSelect, getCharSelect] = room.makeAction<CharacterSelectPayload>(CharacterActions.SELECT);

  // If this is the DM, listen for player actions and update game state
  if (isRoomCreator) {
    // Handle character creation requests from players
    getCharCreate(({ character, playerId }, peerId) => {
      console.log(`Player ${playerId} requested to create character:`, character);
      const newId = crypto.randomUUID();
      const newCharacter: Character = { ...character, id: newId };
      
      onGameStateChange({
        ...gameState,
        party: [...gameState.party, newCharacter]
      });
    });

    // Handle character update requests
    getCharUpdate(({ id, updates, playerId }, peerId) => {
      console.log(`Player ${playerId} requested to update character ${id}:`, updates);
      onGameStateChange({
        ...gameState,
        party: gameState.party.map(char =>
          char.id === id ? { ...char, ...updates } : char
        )
      });
    });

    // Handle character deletion requests
    getCharDelete(({ id, playerId }, peerId) => {
      console.log(`Player ${playerId} requested to delete character ${id}`);
      onGameStateChange({
        ...gameState,
        party: gameState.party.filter(char => char.id !== id)
      });
    });

    // Handle character selection
    getCharSelect(({ characterId, playerId }, peerId) => {
      console.log(`Player ${playerId} selected character ${characterId}`);
      onGameStateChange({
        ...gameState,
        party: gameState.party.map(char =>
          char.id === characterId
            ? { ...char, playerId }
            : char.playerId === playerId
            ? { ...char, playerId: undefined }
            : char
        )
      });
    });
  }

  // Return functions that both DM and players can use to send actions
  return {
    createCharacter: (character: Omit<Character, 'id'>) => {
      console.log(`Sending character creation request from ${selfId}`);
      return sendCharCreate({
        character,
        playerId: selfId
      });
    },

    updateCharacter: (id: string, updates: Partial<Character>) => {
      console.log(`Sending character update request for ${id} from ${selfId}`);
      return sendCharUpdate({
        id,
        updates,
        playerId: selfId
      });
    },

    deleteCharacter: (id: string) => {
      console.log(`Sending character deletion request for ${id} from ${selfId}`);
      return sendCharDelete({
        id,
        playerId: selfId
      });
    },

    selectCharacter: (characterId: string) => {
      console.log(`Sending character selection request for ${characterId} from ${selfId}`);
      return sendCharSelect({
        characterId,
        playerId: selfId
      });
    }
  };
}

// Hook to use character actions
export function useCharacterActions(
  room: Room | undefined,
  gameState: GameState,
  onGameStateChange: (newState: GameState) => void,
  isRoomCreator: boolean
) {
  if (!room) {
    return {
      createCharacter: () => Promise.resolve(),
      updateCharacter: () => Promise.resolve(),
      deleteCharacter: () => Promise.resolve(),
      selectCharacter: () => Promise.resolve()
    };
  }

  return setupCharacterActions(room, gameState, onGameStateChange, isRoomCreator);
}