import React, { useState } from 'react';
import { GameState, Item, Skill, InventorySlot } from '../../../types/game';
import { useItemActions } from '../../../actions/itemActions';
import { useSkillActions } from '../../../actions/skillActions';
import { imageManager } from '../../../services/ImageManager';
import { Plus,Image as ImageIcon } from 'lucide-react';
import { ItemEditor } from '../ItemEditor';
import { SkillEditor } from '../SkillEditor';

interface CatalogTabProps {
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
  room?: Room;
}



export function CatalogTab({ gameState, onGameStateChange, room }: CatalogTabProps) {
  const [selectedCharacters, setSelectedCharacters] = useState<Set<string>>(new Set());
  const [showCreateItem, setShowCreateItem] = useState(false);
  const [showCreateSkill, setShowCreateSkill] = useState(false);
  const [itemThumbnails, setItemThumbnails] = useState<Record<string, string>>({});

  
  const itemActions = useItemActions(room, gameState, onGameStateChange, true);
  const skillActions = useSkillActions(room, gameState, onGameStateChange, true);

  // Load thumbnails for items
  React.useEffect(() => {
    const loadThumbnails = async () => {
      const thumbnails: Record<string, string> = {};
      for (const item of gameState.globalCollections.items) {
        if (item.image) {
          const thumbnail = imageManager.getThumbnail(item.image);
          if (thumbnail) {
            thumbnails[item.id] = thumbnail;
          }
        }
      }
      setItemThumbnails(thumbnails);
    };

    loadThumbnails();
  }, [gameState.globalCollections.items]);

  const handleCharacterSelect = (characterId: string) => {
    setSelectedCharacters(prev => {
      const newSet = new Set(prev);
      if (newSet.has(characterId)) {
        newSet.delete(characterId);
      } else {
        newSet.add(characterId);
      }
      return newSet;
    });
  };

  const handleCreateItem = async (item: Omit<Item, 'id'>) => {
    if (!itemActions) return;
    
    try {
      // Create the item through actions
      await itemActions.createItem(item);
      
      // Also update the local state directly to ensure the UI reflects the change
      const newId = crypto.randomUUID(); // Generate a temporary ID
      const newItem: Item = { ...item, id: newId };
      
      onGameStateChange({
        ...gameState,
        globalCollections: {
          ...gameState.globalCollections,
          items: [...gameState.globalCollections.items, newItem]
        }
      });
      
      setShowCreateItem(false);
    } catch (error) {
      console.error('Failed to create item:', error);
    }
  };

  const handleCreateSkill = async (skill: Omit<Skill, 'id'>) => {
    if (!skillActions) return;
    
    try {
      // Create the skill through actions
      await skillActions.createSkill(skill);
      
      // Also update the local state directly
      const newId = crypto.randomUUID(); // Generate a temporary ID
      const newSkill: Skill = { ...skill, id: newId };
      
      onGameStateChange({
        ...gameState,
        globalCollections: {
          ...gameState.globalCollections,
          skills: [...gameState.globalCollections.skills, newSkill]
        }
      });
      
      setShowCreateSkill(false);
    } catch (error) {
      console.error('Failed to create skill:', error);
    }
  };

  const handleGiveItem = async (item: Item) => {
    if (!itemActions) return;

    try {
      // Convert Set to Array for iteration
      Array.from(selectedCharacters).forEach(async (characterId) => {
        // Find the character in the party
        const character = gameState.party.find(char => char.id === characterId);
        if (!character) return;

        // Add item to character's inventory
        const existingItemSlot = character.inventory.find(([invItem]) => invItem.id === item.id);
        let updatedInventory: InventorySlot[];

        if (existingItemSlot) {
          // Update quantity if item already exists
          updatedInventory = character.inventory.map(([invItem, count]): InventorySlot => 
            invItem.id === item.id ? [invItem, count + 1] : [invItem, count]
          );
        } else {
          // Add new item if it doesn't exist
          updatedInventory = [...character.inventory, [item, 1] as InventorySlot];
        }

        // Update character in party
        const updatedParty = gameState.party.map(char =>
          char.id === characterId
            ? { ...char, inventory: updatedInventory }
            : char
        );

        // Update game state
        onGameStateChange({
          ...gameState,
          party: updatedParty
        });

        // Send the action through the network
        await itemActions.giveItem(item.id, 'global', characterId, 1);
      });
    } catch (error) {
      console.error('Failed to give item:', error);
    }
  };

  const handleTeachSkill = async (skill: Skill) => {
    if (!skillActions) return;

    try {
      // Convert Set to Array for iteration
      Array.from(selectedCharacters).forEach(async (characterId) => {
        // Find the character in the party
        const character = gameState.party.find(char => char.id === characterId);
        if (!character) return;

        // Check if character already has the skill
        if (character.skills.some(existingSkill => existingSkill.id === skill.id)) {
          console.log(`Character ${character.name} already knows this skill`);
          return;
        }

        // Add skill to character's skills
        const updatedSkills = [...character.skills, { ...skill }];

        // Update character in party
        const updatedParty = gameState.party.map(char =>
          char.id === characterId
            ? { ...char, skills: updatedSkills }
            : char
        );

        // Update game state
        onGameStateChange({
          ...gameState,
          party: updatedParty
        });

        // Send the action through the network
        await skillActions.learnSkill(skill.id, characterId);
      });
    } catch (error) {
      console.error('Failed to teach skill:', error);
    }
  };
  const handleGiveItemWithFeedback = async (item: Item) => {
    try {
      await handleGiveItem(item);
      // Could add a toast or other UI feedback here
      console.log('Successfully gave item to selected characters');
    } catch (error) {
      console.error('Failed to give item:', error);
      // Could add error UI feedback here
    }
  };

  const handleTeachSkillWithFeedback = async (skill: Skill) => {
    try {
      await handleTeachSkill(skill);
      // Could add a toast or other UI feedback here
      console.log('Successfully taught skill to selected characters');
    } catch (error) {
      console.error('Failed to teach skill:', error);
      // Could add error UI feedback here
    }
  };
  return (
    <div className="">
      {/* Character Selection Section */}
      <div>
        <h3 className="text-lg font-bold mb-2">Select Characters</h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-2">
          {gameState.party.map(character => (
            <div
              key={character.id}
              className={`p-2 border rounded cursor-pointer ${
                selectedCharacters.has(character.id) ? 'bg-blue-100 border-blue-500' : 'bg-white'
              }`}
              onClick={() => handleCharacterSelect(character.id)}
            >
              <div className="font-medium">{character.name}</div>
              {character.playerId && <div className="text-sm text-gray-500">Player: {character.playerId}</div>}
            </div>
          ))}
        </div>
      </div>

      {/* Items Section */}
      <div>
        <div className="flex justify-between items-center mb-2">
          <h3 className="text-lg font-bold">Items</h3>
          <button
            onClick={() => setShowCreateItem(true)}
            className="flex items-center gap-2 px-3 py-1 bg-green-600 text-white rounded-md hover:bg-green-700"
          >
            <Plus size={16} />
            New Item
          </button>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
          {gameState.globalCollections.items.map(item => (
            <div key={item.id} className="p-4 border rounded bg-white">
              <div className="flex gap-4">
                {/* Image section */}
                <div className="w-20 h-20 flex-shrink-0">
                  {itemThumbnails[item.id] ? (
                    <img
                      src={itemThumbnails[item.id]}
                      alt={item.name}
                      className="w-full h-full object-cover rounded"
                    />
                  ) : (
                    <div className="w-full h-full bg-gray-100 rounded flex items-center justify-center">
                      <ImageIcon className="text-gray-400" size={24} />
                    </div>
                  )}
                </div>
                
                {/* Item details */}
                <div className="flex-grow">
                  <div className="font-medium">{item.name}</div>
                  <div className="text-sm text-gray-600">{item.description}</div>
                  {item.uses !== undefined && (
                    <div className="text-sm text-gray-500">Uses: {item.uses}</div>
                  )}
                  {item.isEquippable && (
                    <div className="text-sm text-blue-500">Equippable</div>
                  )}
                  <button
                    onClick={() => handleGiveItemWithFeedback(item)}
                    disabled={selectedCharacters.size === 0}
                    className="mt-2 px-3 py-1 text-sm bg-blue-50 text-blue rounded hover:bg-blue-100 disabled:text-gray-500 disabled:hover:bg-blue-50"
                  >
                    Give
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div>
  <div className="flex justify-between items-center mb-2">
    <h3 className="text-lg font-bold">Skills</h3>
    <button
      onClick={() => setShowCreateSkill(true)}
      className="flex items-center gap-2 px-3 py-1 bg-purple-600 text-white rounded-md hover:bg-purple-700"
    >
      <Plus size={16} />
      New Skill
    </button>
  </div>
  <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-2">
    {gameState.globalCollections.skills.map(skill => (
      <div key={skill.id} className="p-3 border rounded bg-white">
        <div className="flex justify-between items-start gap-4">
          {skill.image && (
            <div className="w-16 h-16 flex-shrink-0">
              <img
                src={imageManager.getThumbnail(skill.image) || '/placeholder.png'}
                alt={skill.name}
                className="w-full h-full object-cover rounded"
              />
            </div>
          )}
          <div className="flex-1 min-w-0">
            <div className="font-medium truncate">{skill.name}</div>
            <div className="text-sm text-gray-600 line-clamp-2">{skill.description}</div>
            <div className="text-sm text-gray-500 mt-1">
              <span className="mr-3">Damage: {skill.damage}</span>
              <span>SP Cost: {skill.spCost}</span>
            </div>
            {skill.uses !== undefined && (
              <div className="text-sm text-gray-500">
                Uses: {skill.uses}
              </div>
            )}
          </div>
          <button
            onClick={() => handleTeachSkillWithFeedback(skill)}
            disabled={selectedCharacters.size === 0}
            className="px-2 py-1 text-sm bg-purple-50 text-purple-600 rounded hover:bg-purple-100 disabled:text-gray-500 disabled:hover:bg-purple-50 whitespace-nowrap"
          >
            Teach
          </button>
        </div>
      </div>
    ))}
  </div>
</div>

      {/* Create Item Modal */}
      {showCreateItem && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg max-w-md w-full">
            <div className="flex items-center justify-between p-4 border-b">
              <h3 className="text-lg font-bold">Create New Item</h3>
              <button onClick={() => setShowCreateItem(false)}>&times;</button>
            </div>
            <ItemEditor
              onSubmit={handleCreateItem}
              onCancel={() => setShowCreateItem(false)}
            />
          </div>
        </div>
      )}

      {/* Create Skill Modal */}
      {showCreateSkill && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg max-w-md w-full">
            <div className="flex items-center justify-between p-4 border-b">
              <h3 className="text-lg font-bold">Create New Skill</h3>
              <button onClick={() => setShowCreateSkill(false)}>&times;</button>
            </div>
            <SkillEditor
              onSubmit={handleCreateSkill}
              onCancel={() => setShowCreateSkill(false)}
            />
          </div>
        </div>
      )}
    </div>
  );
}