import React from 'react';
import { Character, Entity, isCharacter } from '../../types/game';
import { Plus, Minus } from 'lucide-react';

type CharacterStatType = 'hp' | 'mp' | 'sp';
type EntityStatType = 'hp' | 'sp';

interface BaseStatGaugesProps {
  editable?: boolean;
}

interface CharacterStatGaugesProps extends BaseStatGaugesProps {
  character: Character;
  onStatChange?: (statType: CharacterStatType, newValue: number) => void;
}

interface EntityStatGaugesProps extends BaseStatGaugesProps {
  character: Entity;
  onStatChange?: (statType: EntityStatType, newValue: number) => void;
}

type StatGaugesProps = CharacterStatGaugesProps | EntityStatGaugesProps;

// Type-safe way to get max stat values
const getMaxStat = (character: Character | Entity, statType: CharacterStatType | EntityStatType): number => {
  switch (statType) {
    case 'hp':
      return character.maxHp;
    case 'mp':
      return isCharacter(character) ? character.maxMp : 0;
    case 'sp':
      return character.maxSp;
    default:
      return 0;
  }
};

// Type-safe way to get current stat values
const getCurrentStat = (character: Character | Entity, statType: CharacterStatType | EntityStatType): number => {
  switch (statType) {
    case 'hp':
      return character.hp;
    case 'mp':
      return isCharacter(character) ? character.mp : 0;
    case 'sp':
      return character.sp;
    default:
      return 0;
  }
};

const StatGauge = ({ 
  current, 
  max, 
  label, 
  color,
  onIncrement,
  onDecrement,
  editable
}: { 
  current: number; 
  max: number; 
  label: string; 
  color: string;
  onIncrement?: () => void;
  onDecrement?: () => void;
  editable?: boolean;
}) => {
  const percentage = Math.min(100, Math.max(0, (current / max) * 100));
  
  return (
    <div className="flex flex-col w-full">
      <div className="flex justify-between items-center mb-1">
        <span className="text-sm font-medium">{label}</span>
        <div className="flex items-center gap-2">
          {editable && (
            <button
              onClick={onDecrement}
              className="p-1 rounded hover:bg-gray-100 text-gray-700 transition-colors"
              disabled={current <= 0}
            >
              <Minus size={16} className={current <= 0 ? "text-gray-300" : "text-gray-700"} />
            </button>
          )}
          <span className="text-sm font-mono min-w-[60px] text-center">
            {current}/{max}
          </span>
          {editable && (
            <button
              onClick={onIncrement}
              className="p-1 rounded hover:bg-gray-100 text-gray-700 transition-colors"
              disabled={current >= max}
            >
              <Plus size={16} className={current >= max ? "text-gray-300" : "text-gray-700"} />
            </button>
          )}
        </div>
      </div>
      <div className="h-4 bg-gray-200 rounded-full overflow-hidden">
        <div 
          className={`h-full transition-all duration-300 ${color}`}
          style={{ width: `${percentage}%` }}
        >
          <div className="w-full h-full opacity-20 bg-gradient-to-r from-white via-transparent to-white animate-shimmer" />
        </div>
      </div>
    </div>
  );
};

export default function StatGauges(props: StatGaugesProps) {
  const { character, onStatChange, editable = true } = props;

  const handleStatChange = (
    statType: CharacterStatType | EntityStatType,
    delta: number
  ) => {
    if (!onStatChange) return;
    
    const current = getCurrentStat(character, statType);
    const max = getMaxStat(character, statType);
    const newValue = Math.min(max, Math.max(0, current + delta));
    
    if (newValue !== current) {
      if (isCharacter(character)) {
        // Check if onStatChange exists and is a character stat handler
        const characterStatChange = onStatChange as CharacterStatGaugesProps['onStatChange'];
        if (characterStatChange) {
          characterStatChange(statType as CharacterStatType, newValue);
        }
      } else {
        // Check if onStatChange exists and is an entity stat handler
        const entityStatChange = onStatChange as EntityStatGaugesProps['onStatChange'];
        if (entityStatChange && statType !== 'mp') { // Skip MP changes for entities
          entityStatChange(statType as EntityStatType, newValue);
        }
      }
    }
  };

  return (
    <div className="space-y-4 w-full max-w-md p-4 bg-white rounded-lg shadow">
      <StatGauge
        current={character.hp}
        max={character.maxHp}
        label="HP"
        color="bg-red-500"
        onIncrement={() => handleStatChange('hp', 1)}
        onDecrement={() => handleStatChange('hp', -1)}
        editable={editable}
      />
      
      {/* Only show MP gauge for Characters */}
      {isCharacter(character) && (
        <StatGauge
          current={character.mp}
          max={character.maxMp}
          label="MP"
          color="bg-blue-500"
          onIncrement={() => handleStatChange('mp', 1)}
          onDecrement={() => handleStatChange('mp', -1)}
          editable={editable}
        />
      )}
      
      <StatGauge
        current={character.sp}
        max={character.maxSp}
        label="SP"
        color="bg-green-500"
        onIncrement={() => handleStatChange('sp', 1)}
        onDecrement={() => handleStatChange('sp', -1)}
        editable={editable}
      />
      
      <div className="text-xs text-gray-500 mt-2">
        SP Regen Rate: {character.spRegenRate}/turn
      </div>
    </div>
  );
}