import React, { useCallback, useRef, useState } from 'react';
import { Upload } from 'lucide-react';
import type { GameState } from '../../types/game';
import { imageManager } from '../../services/ImageManager';


interface ImportSaveDialogProps {
  gameState: GameState;
  onImport: (newGameState: GameState) => void;
}

interface BundledSaveFile {
  gameState: GameState;
  images: {
    [imageId: string]: {
      data: string; // base64 encoded image data
      metadata: {
        name: string;
        type: string;
        size: number;
      };
      thumbnail: string;
    };
  };
}

const ImportSaveDialog = ({ gameState, onImport }: ImportSaveDialogProps) => {
  const [error, setError] = useState<string>('');
  const [success, setSuccess] = useState<string>('');
  const [importProgress, setImportProgress] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isImporting, setIsImporting] = useState(false);

  const mergeGameStates = (current: GameState, imported: GameState): GameState => {
    // Create maps for quick lookups using IDs
    const existingPartyIds = new Set(current.party.map(char => char.id));
    const existingItemIds = new Set(current.globalCollections.items.map(item => item.id));
    const existingSkillIds = new Set(current.globalCollections.skills.map(skill => skill.id));
    const existingStatusEffectIds = new Set(current.globalCollections.statusEffects.map(effect => effect.id));
    const existingEntityIds = new Set(current.globalCollections.entities.map(entity => entity.id));
    const existingImageIds = new Set(current.globalCollections.images.map(image => image.id));

    // Merge party (only add new characters)
    const mergedParty = [
      ...current.party,
      ...imported.party.filter(char => !existingPartyIds.has(char.id))
        .map(char => ({ ...char, playerId: undefined })) // Clear player associations
    ];

    // Merge global collections
    const mergedGlobalCollections = {
      items: [
        ...current.globalCollections.items,
        ...imported.globalCollections.items.filter(item => !existingItemIds.has(item.id))
      ],
      skills: [
        ...current.globalCollections.skills,
        ...imported.globalCollections.skills.filter(skill => !existingSkillIds.has(skill.id))
      ],
      statusEffects: [
        ...current.globalCollections.statusEffects,
        ...imported.globalCollections.statusEffects.filter(effect => !existingStatusEffectIds.has(effect.id))
      ],
      entities: [
        ...current.globalCollections.entities,
        ...imported.globalCollections.entities.filter(entity => !existingEntityIds.has(entity.id))
      ],
      images: [
        ...current.globalCollections.images,
        ...imported.globalCollections.images.filter(image => !existingImageIds.has(image.id))
      ]
    };

    return {
      ...current,
      party: mergedParty,
      globalCollections: mergedGlobalCollections,
    };
  };

  const handleFileChange = useCallback(async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    setError('');
    setSuccess('');
    setImportProgress('Reading save file...');

    try {
      const text = await file.text();
      const importedData = JSON.parse(text);
      
      // Check if this is a bundled save file
      const isBundled = importedData.hasOwnProperty('gameState') && importedData.hasOwnProperty('images');
      
      let importedState: GameState;
      if (isBundled) {
        const bundledSave = importedData as BundledSaveFile;
        importedState = bundledSave.gameState;
        
        // Process bundled images
        const totalImages = Object.keys(bundledSave.images).length;
        let processedImages = 0;
        
        for (const [imageId, imageData] of Object.entries(bundledSave.images)) {
          setImportProgress(`Importing images (${processedImages + 1}/${totalImages})...`);
          
          try {
            // Convert base64 to Blob
            const response = await fetch(imageData.data);
            const blob = await response.blob();
            
            // Create File object
            const file = new File([blob], imageData.metadata.name, {
              type: imageData.metadata.type,
              lastModified: Date.now()
            });

            // Store in ImageManager
            await imageManager.addReceivedImage(file, {
              id: imageId,
              name: imageData.metadata.name,
              description: `Imported image: ${imageData.metadata.name}`,
              createdAt: Date.now(),
              size: imageData.metadata.size,
              type: imageData.metadata.type,
              thumbnail: imageData.thumbnail
            });

            processedImages++;
          } catch (err) {
            console.error(`Failed to import image ${imageId}:`, err);
            // Continue with other images
          }
        }
      } else {
        importedState = importedData as GameState;
      }

      // Validate the imported state has the expected structure
      if (!importedState.party || !importedState.globalCollections) {
        throw new Error('Invalid save file format');
      }

      // Merge the imported state with current state
      const mergedState = mergeGameStates(gameState, importedState);
      
      // Call the onImport callback with merged state
      onImport(mergedState);
      
      setError('');
      setSuccess(`Save file imported successfully!${isBundled ? ' (Including bundled images)' : ''}`);
      
      // Reset file input
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }

      // Clear success message after 3 seconds
      setTimeout(() => {
        setSuccess('');
      }, 3000);
    } catch (err) {
      setError('Failed to import save file. Please ensure it is a valid Quest-Net save file.');
      console.error('Import error:', err);
    } finally {
      setIsImporting(false);
      setImportProgress('');
    }
  }, [gameState, onImport]);

  return (
    <div className="space-y-4">
      <input
        type="file"
        accept=".json"
        onChange={handleFileChange}
        ref={fileInputRef}
        className="hidden"
        id="save-file-input"
      />
      
      <div className="relative">
        <label
          htmlFor="save-file-input"
          className={`inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-md 
            hover:bg-blue-700 transition-colors gap-2 cursor-pointer
            ${isImporting ? 'opacity-50 cursor-not-allowed' : ''}`}
        >
          <Upload className="w-4 h-4" />
          Import Save File
        </label>

        {importProgress && (
          <div className="absolute top-full left-0 mt-2 p-3 bg-blue-100 border border-blue-400 text-blue-700 rounded-md">
            {importProgress}
          </div>
        )}

        {error && (
          <div className="absolute top-full left-0 mt-2 p-3 bg-red-100 border border-red-400 text-red-700 rounded-md">
            {error}
          </div>
        )}

        {success && (
          <div className="absolute top-full left-0 mt-2 p-3 bg-green-100 border border-green-400 text-green-700 rounded-md">
            {success}
          </div>
        )}
      </div>
    </div>
  );
};

export default ImportSaveDialog;