import React, { useState, useEffect, useRef } from 'react';
import { searchService, type SearchResult, type TagGroup  } from '../../services/SearchService';
import { GameState } from '../../types/game';
import { Search, Tag } from 'lucide-react';
import { useDebounce } from '../../hooks/useDebounce';

interface SearchBarProps {
  gameState: GameState;
  onResultSelect: (result: {
    id: string;
    type: 'item' | 'skill' | 'character' | 'entity' | 'image';
    location: {
      type: 'catalog' | 'inventory' | 'equipment' | 'field' | 'visuals' | 'encounters';
      containerId?: string;
    };
  }) => void;
  placeholder?: string;
  className?: string;
}

export function SearchBar({ 
  gameState, 
  onResultSelect,
  placeholder = "Search items, characters, or tags...", 
  className = ""
}: SearchBarProps) {
  const [query, setQuery] = useState('');
  const [showResults, setShowResults] = useState(false);
  const [results, setResults] = useState<(SearchResult | TagGroup)[]>([]);
  const searchRef = useRef<HTMLDivElement>(null);
  const debouncedQuery = useDebounce(query, 300);

  // Update search index when gameState changes
  useEffect(() => {
    searchService.updateIndex(gameState);
  }, [gameState]);

  // Perform search when debounced query changes
  useEffect(() => {
    if (debouncedQuery) {
      const searchResults = searchService.search(debouncedQuery);
      setResults(searchResults);
    } else {
      setResults([]);
    }
  }, [debouncedQuery]);

  // Handle clicks outside of search component
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setShowResults(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleResultClick = (result: SearchResult | TagGroup) => {
    if ('tag' in result) {
      // Handle tag group click - maybe expand to show all items with this tag?
      console.log(`Tag group clicked: ${result.tag}`);
      // You could set a new state here to expand this group
      // or trigger a filtered search
    } else {
      onResultSelect(result.object);
      setQuery('');
      setShowResults(false);
    }
  };

  return (
    <div ref={searchRef} className="relative flex-1 max-w-xl mx-auto">
      <div className="relative">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
        <input
          type="text"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setShowResults(true);
          }}
          onFocus={() => setShowResults(true)}
          placeholder={placeholder}
          className={`
            w-full px-10 py-2 text-sm rounded-md
            bg-white dark:bg-black
            text-gray-900 dark:text-gray-100
            border border-gray-200 dark:border-gray-700
            focus:outline-none focus:ring-2 focus:ring-blue-500
            placeholder:text-gray-400 dark:placeholder:text-gray-500
            ${className}
          `}
        />
      </div>

      {/* Results dropdown */}
      {showResults && results.length > 0 && (
        <div className="absolute w-full mt-1 bg-white dark:bg-gray-800 rounded-md shadow-lg border border-gray-200 dark:border-gray-700 max-h-96 overflow-y-auto z-50 divide-y divide-gray-100 dark:divide-gray-700">
          {results.map((result, index) => {
            if ('tag' in result) {
              // Tag group header
              return (
                <div key={`tag-${result.tag}`}>
                  <div className="px-4 py-2 bg-gray-50 dark:bg-gray-700/50 flex items-center gap-2">
                    <Tag className="h-4 w-4 text-blue-500" />
                    <span className="font-medium text-gray-700 dark:text-gray-300">
                      {result.tag}
                    </span>
                    <span className="text-sm text-gray-500 dark:text-gray-400">
                      ({result.objects.length} items)
                    </span>
                  </div>
                  {/* Tag group contents */}
                  <div className="divide-y divide-gray-100 dark:divide-gray-700">
                    {result.objects.map((obj, objIndex) => (
                      <div
                        key={`${obj.id}-${objIndex}`}
                        onClick={() => onResultSelect(obj)}
                        className="px-6 py-2 hover:bg-gray-50 dark:hover:bg-gray-700/50 cursor-pointer"
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            <span className="font-normal">{obj.name}</span>
                            <span className="text-sm text-gray-500 dark:text-gray-400">
                              ({obj.type})
                            </span>
                          </div>
                          <span className="text-sm text-gray-400 dark:text-gray-500">
                            {obj.location.containerName
                              ? `in ${obj.location.containerName}'s ${obj.location.type}`
                              : `in ${obj.location.type}`}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              );
            } else {
              // Direct match
              return (
                <div
                  key={`direct-${result.object.id}-${index}`}
                  onClick={() => handleResultClick(result)}
                  className="px-4 py-2 hover:bg-gray-50 dark:hover:bg-gray-700/50 cursor-pointer"
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <span className="font-normal">{result.object.name}</span>
                      <span className="text-sm text-gray-500 dark:text-gray-400">
                        ({result.object.type})
                      </span>
                    </div>
                    <span className="text-sm text-gray-400 dark:text-gray-500">
                      {result.object.location.containerName
                        ? `in ${result.object.location.containerName}'s ${result.object.location.type}`
                        : `in ${result.object.location.type}`}
                    </span>
                  </div>
                </div>
              );
            }
          })}
        </div>
      )}
    </div>
  );
}