import React from 'react';
import { Scroll, Sword, Zap } from 'lucide-react';

interface CharacterControlsProps {
  onOpenInventory: () => void;
  onOpenEquipment: () => void;
  onOpenSkills: () => void;
}

export function CharacterControls({
  onOpenInventory,
  onOpenEquipment,
  onOpenSkills
}: CharacterControlsProps) {
  return (
    <div className="flex gap-2 mt-4">
      <button
        onClick={onOpenInventory}
        className="flex items-center gap-2 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-800 rounded-md transition-colors"
      >
        <Scroll className="w-4 h-4" />
        Inventory
      </button>
      
      <button
        onClick={onOpenEquipment}
        className="flex items-center gap-2 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-800 rounded-md transition-colors"
      >
        <Sword className="w-4 h-4" />
        Equipment
      </button>
      
      <button
        onClick={onOpenSkills}
        className="flex items-center gap-2 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-800 rounded-md transition-colors"
      >
        <Zap className="w-4 h-4" />
        Skills
      </button>
    </div>
  );
}