import React, { useState, useEffect, useCallback } from 'react';
import { Character, SerializableCharacter } from '../../types/game';
import { imageManager } from '../../services/ImageManager';

interface CharacterEditorProps {
  character?: Character;
  onSave: (character: Omit<SerializableCharacter, 'id'>) => void;
  onUpdate: (id: string, updates: Partial<Character>) => void;
  onDelete?: (id: string) => void;
  onClose: () => void;
  isRoomCreator: boolean;
}

export function CharacterEditor({ 
  character, 
  onSave, 
  onUpdate, 
  onDelete,
  onClose,
  isRoomCreator 
}: CharacterEditorProps) {
  const [form, setForm] = useState<Omit<SerializableCharacter, 'id' | 'playerId'>>({
    name: '',
    description: '',
    image: '',
    maxHp: 10,
    hp: 10,
    maxMp: 10,
    mp: 10,
    maxSp: 10,
    sp: 10,
    spRegenRate: 1,
    equipment: [],
    inventory: [],
    skills: [],
    statusEffects: []
  });

  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    if (character) {
      const { id, playerId, ...characterData } = character;
      setForm(characterData);
      setImagePreview(characterData.image || null);
    }
  }, [character]);
  useEffect(() => {
    if (character?.image) {
      // First try to get the thumbnail which is faster
      const thumbnail = imageManager.getThumbnail(character.image);
      if (thumbnail) {
        setImagePreview(thumbnail);
      }

      // Then load the full image
      imageManager.getImage(character.image)
        .then(file => {
          if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
              const dataUrl = reader.result as string;
              setImagePreview(dataUrl);
            };
            reader.readAsDataURL(file);
          }
        })
        .catch(error => {
          console.error('Failed to load character image:', error);
          setImagePreview(null);
        });
    }
  }, [character?.image]);
  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!form.name.trim()) {
      newErrors.name = 'Name is required';
    }

    if (!form.description.trim()) {
      newErrors.description = 'Description is required';
    }

    if (form.maxHp < 1) {
      newErrors.maxHp = 'Max HP must be at least 1';
    }

    if (form.maxMp < 0) {
      newErrors.maxMp = 'Max MP cannot be negative';
    }

    if (form.maxSp < 0) {
      newErrors.maxSp = 'Max SP cannot be negative';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleImageUpload = useCallback(async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      setErrors(prev => ({ ...prev, image: 'Please upload an image file' }));
      return;
    }

    const MAX_SIZE = 5 * 1024 * 1024;
    if (file.size > MAX_SIZE) {
      setErrors(prev => ({ ...prev, image: 'Image must be smaller than 5MB' }));
      return;
    }

    try {
      setIsUploading(true);

      // Store in ImageManager first
      const imageData = await imageManager.addImage(file);
      
      // Use the thumbnail for preview
      setImagePreview(imageData.thumbnail);
      
      // Set the image ID in the form
      setForm(prev => ({ ...prev, image: imageData.id }));
      
      setIsUploading(false);
      setErrors(prev => {
        const { image, ...rest } = prev;
        return rest;
      });
    } catch (error) {
      console.error('Error uploading image:', error);
      setErrors(prev => ({ ...prev, image: 'Failed to upload image' }));
      setIsUploading(false);
    }
  }, []);

  const handleMaxStatChange = (
    stat: 'maxHp' | 'maxMp' | 'maxSp',
    value: number
  ) => {
    setForm(prev => {
      const newMax = Math.max(1, value);
      return {
        ...prev,
        [stat]: newMax,
        // Set the current value to match max for new characters
        [stat.replace('max', '').toLowerCase()]: newMax
      };
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateForm()) return;

    if (character?.id) {
      onUpdate(character.id, form);
    } else {
      onSave(form);
    }
    onClose();
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div>
        <label className="block text-sm font-medium">Name</label>
        <input
          type="text"
          value={form.name}
          onChange={e => {
            setForm(prev => ({ ...prev, name: e.target.value }));
            if (errors.name) {
              setErrors(prev => {
                const { name, ...rest } = prev;
                return rest;
              });
            }
          }}
          className={`mt-1 w-full rounded-md border p-2 ${
            errors.name ? 'border-red-500' : 'border-gray-300'
          }`}
          required
        />
        {errors.name && <p className="mt-1 text-sm text-red-500">{errors.name}</p>}
      </div>

      <div>
        <label className="block text-sm font-medium">Description</label>
        <textarea
          value={form.description}
          onChange={e => {
            setForm(prev => ({ ...prev, description: e.target.value }));
            if (errors.description) {
              setErrors(prev => {
                const { description, ...rest } = prev;
                return rest;
              });
            }
          }}
          className={`mt-1 w-full rounded-md border p-2 ${
            errors.description ? 'border-red-500' : 'border-gray-300'
          }`}
          rows={3}
          required
        />
        {errors.description && (
          <p className="mt-1 text-sm text-red-500">{errors.description}</p>
        )}
      </div>

      <div className="space-y-4">
        <label className="block text-sm font-medium">Character Image</label>
        
        {imagePreview && (
          <div className="mt-2 relative w-32 h-32">
            <img
              src={imagePreview}
              alt="Character preview"
              className="w-full h-full object-cover rounded-md"
              onError={() => setImagePreview(null)}
            />
            <button
              type="button"
              onClick={() => {
                setImagePreview(null);
                setForm(prev => ({ ...prev, image: '' }));
              }}
              className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center"
            >
              ×
            </button>
          </div>
        )}

        <div>
          <input
            type="file"
            accept="image/*"
            onChange={handleImageUpload}
            disabled={isUploading}
            className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
          />
          {isUploading && <p className="text-sm text-gray-500 mt-1">Uploading...</p>}
          {errors.image && <p className="mt-1 text-sm text-red-500">{errors.image}</p>}
        </div>
      </div>

      <div className="flex gap-4">
        <div>
          <label className="block text-sm font-medium">Max HP</label>
          <input
            type="number"
            value={form.maxHp}
            onChange={e => handleMaxStatChange('maxHp', Number(e.target.value))}
            className={`mt-1 w-24 rounded-md border p-2 ${
              errors.maxHp ? 'border-red-500' : 'border-gray-300'
            }`}
            min="1"
            required
          />
          {errors.maxHp && <p className="mt-1 text-sm text-red-500">{errors.maxHp}</p>}
        </div>
        
        <div>
          <label className="block text-sm font-medium">Max MP</label>
          <input
            type="number"
            value={form.maxMp}
            onChange={e => handleMaxStatChange('maxMp', Number(e.target.value))}
            className={`mt-1 w-24 rounded-md border p-2 ${
              errors.maxMp ? 'border-red-500' : 'border-gray-300'
            }`}
            min="0"
            required
          />
          {errors.maxMp && <p className="mt-1 text-sm text-red-500">{errors.maxMp}</p>}
        </div>
        <div>
          <label className="block text-sm font-medium">Max SP</label>
          <input
            type="number"
            value={form.maxSp}
            onChange={e => handleMaxStatChange('maxSp', Number(e.target.value))}
            className={`mt-1 w-24 rounded-md border p-2 ${
              errors.maxSp ? 'border-red-500' : 'border-gray-300'
            }`}
            min="0"
            required
          />
          {errors.maxSp && <p className="mt-1 text-sm text-red-500">{errors.maxSp}</p>}
        </div>
      </div>
            
      <div className="flex justify-end gap-2">
        <button
          type="button"
          onClick={onClose}
          className="px-4 py-2 border rounded-md hover:bg-gray-50"
        >
          Cancel
        </button>
        {character && onDelete && isRoomCreator && (
          <button
            type="button"
            onClick={() => {
              if (window.confirm('Are you sure you want to delete this character?')) {
                onDelete(character.id);
                onClose();
              }
            }}
            className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700"
          >
            Delete
          </button>
        )}
        <button
          type="submit"
          className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-blue-300"
          disabled={isUploading}
        >
          {character ? 'Update' : 'Create'} Character
        </button>
      </div>
    </form>
  );
}