import React, { useState } from 'react';
import { Download } from 'lucide-react';
import type { GameState } from '../../types/game';
import { imageManager } from '../../services/ImageManager';

interface ExportSaveDialogProps {
  gameState: GameState;
}

interface BundledSaveFile {
  gameState: GameState;
  images: {
    [imageId: string]: {
      data: string; // base64 encoded image data
      metadata: {
        name: string;
        type: string;
        size: number;
      };
      thumbnail: string;
    };
  };
}

const ExportSaveDialog = ({ gameState }: ExportSaveDialogProps) => {
  const [isExporting, setIsExporting] = useState(false);
  const [progress, setProgress] = useState<string>('');
  const [error, setError] = useState<string>('');

  // Helper function to convert File to base64
  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        if (typeof reader.result === 'string') {
          resolve(reader.result);
        } else {
          reject(new Error('Failed to convert file to base64'));
        }
      };
      reader.onerror = () => reject(reader.error);
      reader.readAsDataURL(file);
    });
  };

  const stripPlayerIds = (state: GameState): GameState => {
    return {
      ...state,
      party: state.party.map(character => ({
        ...character,
        playerId: undefined
      }))
    };
  };

  const handleExport = async (includeImages: boolean = false) => {
    if (isExporting) return;
    
    setIsExporting(true);
    setError('');
    
    try {
      if (!includeImages) {
        setProgress('Preparing save file...');
        const cleanGameState = {
          ...stripPlayerIds(gameState),
          globalCollections: {
            ...gameState.globalCollections,
            images: []
          },
          display: {
            ...gameState.display,
            environmentImageId: undefined,
            focusImageId: undefined,
            showFocusImage: false
          }
        };

        const saveData = JSON.stringify(cleanGameState, null, 2);
        const blob = new Blob([saveData], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
        const link = document.createElement('a');
        link.href = url;
        link.download = `quest-net-save-${timestamp}.json`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
        return;
      }

      // Export with bundled images
      setProgress('Collecting image data...');
      const bundledSave: BundledSaveFile = {
        gameState: stripPlayerIds(gameState),
        images: {}
      };

      const imageIds = Array.from(new Set(
        gameState.globalCollections.images.map(img => img.id)
      ));

      let processedImages = 0;
      const totalImages = imageIds.length;

      // Process images sequentially to avoid memory issues
      for (const imageId of imageIds) {
        try {
          setProgress(`Processing image ${processedImages + 1}/${totalImages}`);
          
          const file = await imageManager.getImage(imageId);
          const imageData = await imageManager.getImageData(imageId);
          
          if (file && imageData) {
            try {
              const base64Data = await fileToBase64(file);
              
              bundledSave.images[imageId] = {
                data: base64Data,
                metadata: {
                  name: file.name,
                  type: file.type,
                  size: file.size
                },
                thumbnail: imageData.thumbnail
              };
              
              processedImages++;
            } catch (err) {
              console.error(`Failed to process image ${imageId}:`, err);
              // Continue with other images
            }
          }
        } catch (err) {
          console.error(`Failed to load image ${imageId}:`, err);
          // Continue with other images
        }
      }

      if (processedImages === 0) {
        throw new Error('No images were successfully processed');
      }

      setProgress('Creating save file...');
      const saveData = JSON.stringify(bundledSave, null, 2);
      const blob = new Blob([saveData], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      const link = document.createElement('a');
      link.href = url;
      link.download = `quest-net-save-with-images-${timestamp}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
      
    } catch (error) {
      console.error('Failed to export game state:', error);
      setError(error instanceof Error ? error.message : 'Failed to export save file');
    } finally {
      setIsExporting(false);
      setProgress('');
      if (error) {
        setTimeout(() => setError(''), 3000);
      }
    }
  };

  return (
    <div className="relative">
      <div className="flex">
        <button
          onClick={() => handleExport(false)}
          disabled={isExporting}
          className={`inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-l-md 
            hover:bg-blue-700 transition-colors gap-2
            ${isExporting ? 'opacity-50 cursor-not-allowed' : ''}`}
        >
          <Download className="w-4 h-4" />
          Export Save File
        </button>
        <button
          onClick={() => handleExport(true)}
          disabled={isExporting}
          className={`inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-r-md 
            border-l border-blue-500 hover:bg-blue-700 transition-colors
            ${isExporting ? 'opacity-50 cursor-not-allowed' : ''}`}
          title="Include images in save file"
        >
          +Images
        </button>
      </div>

      {progress && (
        <div className="absolute top-full left-0 mt-2 p-3 bg-blue-100 border 
          border-blue-400 text-blue-700 rounded-md whitespace-nowrap">
          {progress}
        </div>
      )}

      {error && (
        <div className="absolute top-full left-0 mt-2 p-3 bg-red-100 border 
          border-red-400 text-red-700 rounded-md whitespace-nowrap">
          {error}
        </div>
      )}
    </div>
  );
};

export default ExportSaveDialog;