import React, { useEffect, useCallback } from 'react';
import { selfId } from 'trystero';
import { PlayerView } from './components/Player/PlayerView';
import { DMView } from './components/DungeonMaster/DMView';
import { GameInterface } from './components/GameInterface';
import LobbySystem from './components/LobbySystem';
import { useRoom } from './hooks/useRoom';
import { useGamePersistence } from './hooks/useGamePersistence';
import { roomManager } from './services/RoomManager';
import type { ConnectionStatusType } from './types/connection';

type TabType = 'characters' | 'visuals' | 'catalog' | 'encounter' | 'battle' | 'settings';

interface GameRoomProps {
  onConnectionUpdate: (
    status: ConnectionStatusType,
    peers: string[],
    error: string,
    roomId: string
  ) => void;
}

function GameRoom({ onConnectionUpdate }: GameRoomProps) {
  const [hasJoinedRoom, setHasJoinedRoom] = React.useState(false);
  const [roomId, setRoomId] = React.useState('');
  const [isRoomCreator, setIsRoomCreator] = React.useState(false);
  // Add state for active tab if needed for navigation
  const [activeTab, setActiveTab] = React.useState<TabType>('characters');

  const {
    peers,
    connectionStatus,
    errorMessage,
    gameState,
    handleGameStateChange,
    room
  } = useRoom(hasJoinedRoom ? roomId : '', isRoomCreator);

  const {
    saveGameState
  } = useGamePersistence(roomId, isRoomCreator);

  const handleJoinRoom = (id: string, isHost: boolean) => {
    setRoomId(id);
    setIsRoomCreator(isHost);
    setHasJoinedRoom(true);
  };

  const handleNavigateToResult = useCallback((result: {
    id: string;
    type: 'item' | 'skill' | 'character' | 'entity' | 'image';
    location: {
      type: 'catalog' | 'inventory' | 'equipment' | 'field' | 'visuals' | 'encounters';
      containerId?: string;
    };
  }) => {
    // Navigate to appropriate tab based on result type and location
    if (isRoomCreator) {
      // DM View navigation
      switch (result.location.type) {
        case 'catalog':
          switch (result.type) {
            case 'item':
            case 'skill':
              setActiveTab('catalog');
              break;
            case 'image':
              setActiveTab('visuals');
              break;
            case 'entity':
              setActiveTab('encounter');
              break;
          }
          break;
        case 'field':
          setActiveTab('encounter');
          break;
        case 'inventory':
        case 'equipment':
          setActiveTab('characters');
          break;
      }
    }
  }, [isRoomCreator]);

  // Update connection status
  useEffect(() => {
    const status = hasJoinedRoom ? connectionStatus : 'disconnected';
    const currentPeers = hasJoinedRoom ? peers : [];
    const error = hasJoinedRoom ? errorMessage : '';
    const currentRoomId = hasJoinedRoom ? roomId : '';
    
    onConnectionUpdate(status, currentPeers, error, currentRoomId);
  }, [connectionStatus, peers, errorMessage, roomId, hasJoinedRoom, onConnectionUpdate]);

  const handleCharacterSelect = (characterId: string) => {
    if (!room) return;
    
    const [sendCharacterSelect] = room.makeAction<{
      playerId: string;
      characterId: string;
    }>('charSelect');

    sendCharacterSelect({
      playerId: selfId,
      characterId
    });
  };

  const handleLeaveRoom = () => {
    if (isRoomCreator) {
      saveGameState(gameState);
    }
    roomManager.leaveRoom();
    setHasJoinedRoom(false);
    setIsRoomCreator(false);
    setRoomId('');
  };

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      roomManager.leaveRoom();
    };
  }, []);

  if (!hasJoinedRoom) {
    return <LobbySystem onJoinRoom={handleJoinRoom} />;
  }

  return (
    <GameInterface
      roomId={roomId}
      peers={peers}
      connectionStatus={connectionStatus}
      errorMessage={errorMessage}
      isRoomCreator={isRoomCreator}
      gameState={gameState}
      onLeaveRoom={handleLeaveRoom}
      onSaveGame={() => saveGameState(gameState)}
      onNavigateToResult={handleNavigateToResult}
    >
      {isRoomCreator ? (
        <DMView 
          gameState={gameState}
          onGameStateChange={handleGameStateChange}
          room={room}
          isRoomCreator={isRoomCreator}
          activeTab={activeTab}
          onTabChange={setActiveTab}
        />
      ) : (
        <PlayerView
          gameState={gameState}
          playerId={selfId}
          onCharacterSelect={handleCharacterSelect}
          room={room}
        />
      )}
    </GameInterface>
  );
}

export default GameRoom;