import React, { useState, useEffect } from 'react';
import { Character } from '../../types/game';
import { imageManager } from '../../services/ImageManager';

interface CharacterSheetProps {
  character: Character;
}

export function CharacterSheet({ character }: CharacterSheetProps) {
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  // Load character image from IndexedDB
  useEffect(() => {
    if (character.image) {
      // First try to get the thumbnail which is faster
      const thumbnail = imageManager.getThumbnail(character.image);
      if (thumbnail) {
        setImageUrl(thumbnail);
      }

      // Then load the full image
      imageManager.getImage(character.image)
        .then(file => {
          if (file) {
            const url = URL.createObjectURL(file);
            setImageUrl(url);
            return url; // Return for cleanup
          }
          return null;
        })
        .catch(error => {
          console.error('Failed to load character image:', error);
        });
    } else {
      setImageUrl(null);
    }

    // Cleanup object URL on unmount or when image changes
    return () => {
      if (imageUrl && !imageUrl.startsWith('data:')) {
        URL.revokeObjectURL(imageUrl);
      }
    };
  }, [character.image, imageUrl]);

  return (
    <div className="border rounded-lg p-6 space-y-4">
      <div className="flex items-start gap-4">
        {imageUrl ? (
          <img 
            src={imageUrl} 
            alt={character.name} 
            className="w-24 h-24 rounded-full object-cover"
          />
        ) : (
          <div className="w-24 h-24 rounded-full bg-gray-200 flex items-center justify-center">
            <span className="text-gray-400 text-2xl">
              {character.name.charAt(0).toUpperCase()}
            </span>
          </div>
        )}
        <div>
          <h2 className="text-2xl font-bold">{character.name}</h2>
          <p className="text-gray-600">{character.description}</p>
        </div>
      </div>

      <div className="mt-4">
        <div className="flex items-center gap-2">
          <div className="font-medium">HP:</div>
          <div className="text-xl">
            {character.hp} / {character.maxHp}
          </div>
        </div>
      </div>
    </div>
  );
}