import React, { useState, useEffect } from 'react';
import { Entity } from '../../types/game';
import { ImageIcon } from 'lucide-react';
import { imageManager } from '../../services/ImageManager';

interface FieldProps {
  field: Entity[];
}

export function Field({ field }: FieldProps) {
  // Add state for entity images
  const [entityImages, setEntityImages] = useState<Record<string, string>>({});

  // Effect to load images for entities
  useEffect(() => {
    const loadEntityImages = async () => {
      const newEntityImages: Record<string, string> = {};
      
      for (const entity of field) {
        if (entity.image) {
          // First try to get the thumbnail which is faster
          const thumbnail = imageManager.getThumbnail(entity.image);
          if (thumbnail) {
            newEntityImages[entity.id] = thumbnail;
            continue;
          }

          // If no thumbnail, try to get the full image
          try {
            const file = await imageManager.getImage(entity.image);
            if (file) {
              const reader = new FileReader();
              reader.onload = () => {
                setEntityImages(prev => ({
                  ...prev,
                  [entity.id]: reader.result as string
                }));
              };
              reader.readAsDataURL(file);
            }
          } catch (error) {
            console.error(`Failed to load image for entity ${entity.id}:`, error);
          }
        }
      }
      
      setEntityImages(newEntityImages);
    };

    loadEntityImages();
  }, [field]);

  if (field.length === 0) {
    return null;
  }

  return (
    <div className="mt-6">
      <h2 className="text-xl font-bold mb-4">Field</h2>
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
        {field.map(entity => (
          <div 
            key={entity.id}
            className="border rounded-lg p-4 bg-white shadow"
          >
            <div className="flex gap-4">
              {/* Image section */}
              <div className="w-20 h-20 flex-shrink-0">
                {entity.image && entityImages[entity.id] ? (
                  <img
                    src={entityImages[entity.id]}
                    alt={entity.name}
                    className="w-full h-full object-cover rounded-md bg-gray-100"
                  />
                ) : (
                  <div className="w-full h-full bg-gray-100 rounded-md flex items-center justify-center">
                    <ImageIcon className="text-gray-400" size={24} />
                  </div>
                )}
              </div>
              
              {/* Entity details */}
              <div className="flex-grow">
                <div className="font-medium text-lg">{entity.name}</div>
                <p className="text-sm text-gray-600 line-clamp-2">
                  {entity.description}
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}