import React, { useState } from 'react';
import type { PlayerViewProps } from '../../types/game';
import { CharacterSheet } from './CharacterSheet';
import StatGauges from './StatGauges';
import { InventoryPanel } from './InventoryPanel';
import { EquipmentPanel } from './EquipmentPanel';
import { SkillsPanel } from './SkillsPanel';
import { CharacterControls } from './CharacterControls';
import { EnvironmentDisplay } from '../shared/ImageDisplay';
import { Field } from './Field';

export function ThreatView({ gameState, playerId, onCharacterSelect, room }: PlayerViewProps) {
  const [showInventory, setShowInventory] = useState(false);
  const [showEquipment, setShowEquipment] = useState(false);
  const [showSkills, setShowSkills] = useState(false);
  
  // Find the selected character
  const selectedCharacter = gameState.party.find(c => c.playerId === playerId);
  
  // Filter out the selected character from the party members display
  const otherPartyMembers = gameState.party.filter(c => c.playerId !== playerId);

  return (
    <div className="grid h-full w-full" style={{
        gridTemplateColumns: '25fr 15fr 40fr 20fr',
        gridTemplateRows: '3fr 7fr',
        gap: '1rem',
        padding: '1rem',
      }}>
      {/* Column 1-2, Row 1: Character Sheet & Stats */}
      <div style={{ gridColumn: '1 / 3', gridRow: '1' }} className="bg-white rounded-lg shadow p-4 overflow-auto">
        {selectedCharacter && (
          <div className="h-full flex flex-col justify-between">
            <CharacterSheet character={selectedCharacter} />
            <div className="mt-4">
              <StatGauges 
                character={selectedCharacter}
                editable={true}
              />
            </div>
            <div className="mt-4">
              <CharacterControls
                onOpenInventory={() => setShowInventory(true)}
                onOpenEquipment={() => setShowEquipment(true)}
                onOpenSkills={() => setShowSkills(true)}
              />
            </div>
          </div>
        )}
      </div>

      {/* Column 3-4, Row 1: Combat Information */}
      <div style={{ gridColumn: '3 / 4', gridRow: '1' }} className="bg-white rounded-lg shadow p-4">
        <h2 className="text-xl font-bold mb-4">Combat Information</h2>
        {gameState.combat && (
          <div className="space-y-2">
            <div className="flex justify-between items-center">
              <span>Turn: {gameState.combat.currentTurn}</span>
              <span>Initiative: {gameState.combat.initiativeSide}</span>
            </div>
          </div>
        )}
      </div>

      {/* Column 1, Row 2: Party Members */}
      <div style={{ gridColumn: '1', gridRow: '2' }} className="bg-white rounded-lg shadow p-4 overflow-auto">
        <h2 className="text-lg font-bold mb-4">Party Members</h2>
        {otherPartyMembers.length === 0 ? (
          <p className="text-gray-500 text-center">No other party members</p>
        ) : (
          <div className="space-y-4">
            {otherPartyMembers.map(character => (
              <div key={character.id} className="border rounded-lg p-4">
                <CharacterSheet character={character} />
                <StatGauges 
                  character={character}
                  editable={false}
                />
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Column 2-3, Row 2: Image Display */}
      <div style={{ gridColumn: '2 / 4', gridRow: '2' }} className="bg-white rounded-lg shadow p-4 overflow-auto">
        <EnvironmentDisplay gameState={gameState} />
      </div>

      {/* Column 4, Row 1-2: Field Entities */}
      <div style={{ gridColumn: '4', gridRow: '1 / 3' }} className="bg-white rounded-lg shadow p-4 overflow-auto">
        <h2 className="text-lg font-bold mb-4">Field Entities</h2>
        <Field field={gameState.field} />
      </div>

      {/* Modals */}
      {showInventory && selectedCharacter && (
        <InventoryPanel
          inventory={selectedCharacter.inventory}
          onClose={() => setShowInventory(false)}
          onUseItem={(itemId) => {
            console.log('Using item:', itemId);
          }}
          onEquipItem={(itemId) => {
            console.log('Equipping item:', itemId);
          }}
        />
      )}

      {showEquipment && selectedCharacter && (
        <EquipmentPanel
          equipment={selectedCharacter.equipment}
          onClose={() => setShowEquipment(false)}
          onUnequipItem={(itemId) => {
            console.log('Unequipping item:', itemId);
          }}
        />
      )}

      {showSkills && selectedCharacter && (
        <SkillsPanel
          skills={selectedCharacter.skills}
          onClose={() => setShowSkills(false)}
          onUseSkill={(skillId) => {
            console.log('Using skill:', skillId);
          }}
        />
      )}
    </div>
  );
}