import React from 'react';
import { Character } from '../../types/game';
import StatGauges from '../Player/StatGauges';

interface CharacterListProps {
  party: Character[];
  onSelectCharacter: (id: string) => void;
  onStatChange?: (characterId: string, statType: 'hp' | 'mp' | 'sp', newValue: number) => void;
}

export function CharacterList({ party, onSelectCharacter, onStatChange }: CharacterListProps) {
  return (
    <div className="space-y-4">
      <h2 className="text-xl font-bold">Party Members</h2>
      <div className="grid gap-4">
        {party.map(character => (
          <div 
            key={character.id}
            className="p-4 border rounded-lg bg-white shadow-sm"
          >
            {/* Character Header */}
            <div className="flex justify-between items-center mb-4">
              <div>
                <h3 className="font-medium">{character.name}</h3>
                <p className="text-sm text-gray-600 mt-1">{character.description}</p>
              </div>
              <button
                onClick={() => onSelectCharacter(character.id)}
                className="px-3 py-1 text-sm bg-blue-50 text-blue-600 rounded-md hover:bg-blue-100"
              >
                Edit
              </button>
            </div>

            {/* Stat Gauges */}
            <StatGauges
              character={character}
              onStatChange={(statType: 'hp' | 'mp' | 'sp', newValue: number) => {
                if (onStatChange) {
                  onStatChange(character.id, statType, newValue);
                }
              }}
              editable={true}
            />

            {/* Player Assignment Info */}
            {character.playerId && (
              <div className="text-sm text-blue-600 mt-4">
                Currently played by: {character.playerId}
              </div>
            )}
          </div>
        ))}

        {party.length === 0 && (
          <div className="text-center py-8 text-gray-500">
            No characters in the party yet
          </div>
        )}
      </div>
    </div>
  );
}