import React, { ReactNode } from 'react';
import type { ConnectionStatusType } from '../types/connection';
import { SlidingToggle } from './ui/ThemeToggle';
import { SearchBar } from './shared/SearchBar';
import { GameState } from '../types/game';

interface GameInterfaceProps {
  roomId: string;
  peers: string[];
  connectionStatus: ConnectionStatusType;
  errorMessage: string;
  isRoomCreator: boolean;
  gameState: GameState;
  onLeaveRoom: () => void;
  onSaveGame: () => void;
  onNavigateToResult: (result: {
    id: string;
    type: 'item' | 'skill' | 'character' | 'entity' | 'image';
    location: {
      type: 'catalog' | 'inventory' | 'equipment' | 'field' | 'visuals' | 'encounters';
      containerId?: string;
    };
  }) => void;
  children: ReactNode;
}

export function GameInterface({
  roomId,
  isRoomCreator,
  gameState,
  onLeaveRoom,
  onSaveGame,
  onNavigateToResult,
  children
}: GameInterfaceProps) {

  const handleSearchSelect = (result: {
    id: string;
    type: 'item' | 'skill' | 'character' | 'entity' | 'image';
    location: {
      type: 'catalog' | 'inventory' | 'equipment' | 'field' | 'visuals' | 'encounters';
      containerId?: string;
    };
  }) => {
    // Pass the navigation request up to the parent component
    onNavigateToResult(result);
  };

  return (
    <div className="fixed inset-0 flex flex-col h-screen w-screen mt-[6.35vmin] overflow-hidden bg-offwhite dark:bg-grey">
      {/* Header */}
      <div className="flex-shrink-0 p-0 backdrop-blur-sm">
        <div className="flex items-center justify-between mb-1 ml-5 mt-3 mr-5">
          <div className="flex flex-row gap-0">
            <button
              onClick={onLeaveRoom}
              className="px-3 py-[0.5vh] text-[1.5vmin] bg-grey text-offwhite dark:border-2 border-offwhite rounded-l-md hover:bg-grey/75 dark:hover:bg-offwhite/25 transition-colors"
            >
              Leave Room
            </button>
            {isRoomCreator && (
              <button
                onClick={onSaveGame}
                className="px-3 py-[0.5vh] text-[1.5vmin] bg-offwhite text-grey border-2 dark:border-0 border-grey rounded-r-md hover:bg-grey/25 dark:hover:bg-offwhite/75 transition-colors"
              >
                Save Game
              </button>
            )}
          </div>
          <SearchBar 
            gameState={gameState}
            onResultSelect={handleSearchSelect}
            placeholder="Search items, skills, characters..."
          />
          <div className="mt-[1.2vmin] ">
          <SlidingToggle />
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 min-h-0">
        {children}
      </div>
    </div>
  );
}