import React from 'react';
import { Skill } from '../../types/game';
import { Zap } from 'lucide-react';

interface SkillsPanelProps {
  skills: Skill[];
  onClose: () => void;
  onUseSkill?: (skillId: string) => void;
}

export function SkillsPanel({
  skills,
  onClose,
  onUseSkill
}: SkillsPanelProps) {
    const isSkillUsable = (skill: Skill): boolean => {
        if (skill.uses === undefined) return true;
        if (skill.usesLeft === undefined) return skill.uses > 0;
        return skill.usesLeft > 0;
      };
    
      // Helper function to display uses text
      const getUsesText = (skill: Skill): string => {
        if (skill.uses === undefined) return 'Unlimited';
        const usesLeft = skill.usesLeft ?? skill.uses;
        return `${usesLeft}/${skill.uses}`;
      };
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col">
        <div className="flex justify-between items-center mb-4">
          <div className="flex items-center gap-2">
            <Zap className="w-5 h-5" />
            <h2 className="text-xl font-bold">Skills</h2>
          </div>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700"
          >
            ×
          </button>
        </div>

        {skills.length === 0 ? (
          <div className="flex-1 flex items-center justify-center text-gray-500">
            No skills learned
          </div>
        ) : (
          <div className="flex-1 overflow-auto">
            <div className="grid gap-2">
              {skills.map(skill => (
                <div
                  key={skill.id}
                  className="p-3 border rounded bg-white shadow-sm"
                >
                  <div className="flex justify-between items-start">
                    <div>
                      <div className="font-medium">{skill.name}</div>
                      <div className="text-sm text-gray-600">
                        {skill.description}
                      </div>
                      <div className="text-sm text-gray-500 mt-2">
                        <span className="mr-4">Damage: {skill.damage}</span>
                        <span className="mr-4">SP Cost: {skill.spCost}</span>
                        <span>Uses: {getUsesText(skill)}</span>
                      </div>
                    </div>
                    {onUseSkill && isSkillUsable(skill) && (
                      <button
                        onClick={() => onUseSkill(skill.id)}
                        className="px-2 py-1 text-sm bg-purple-50 text-purple-600 rounded hover:bg-purple-100"
                      >
                        Use
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}