import React, { useState } from 'react';
import { Character, DMViewProps } from '../../../types/game';
import { CharacterEditor } from '../../shared/CharacterEditor';
import { CharacterList } from '../CharacterList';

export function CharacterTab({ gameState, onGameStateChange, room }: DMViewProps) {
  const [selectedCharacterId, setSelectedCharacterId] = useState<string | null>(null);
  const [showEditor, setShowEditor] = useState(false);

  const selectedCharacter = selectedCharacterId 
    ? gameState.party.find(c => c.id === selectedCharacterId)
    : undefined;

  const handleAddCharacter = (character: Omit<Character, 'id'>) => {
    const newId = crypto.randomUUID();
    const newCharacter: Character = {
      ...character,
      id: newId,
    };

    onGameStateChange({
      ...gameState,
      party: [...gameState.party, newCharacter]
    });
  };

  const handleUpdateCharacter = (id: string, updates: Partial<Character>) => {
    onGameStateChange({
      ...gameState,
      party: gameState.party.map(char =>
        char.id === id ? { ...char, ...updates } : char
      )
    });
  };

  const handleDeleteCharacter = (id: string) => {
    onGameStateChange({
      ...gameState,
      party: gameState.party.filter(char => char.id !== id)
    });
  };

  const handleStatChange = (characterId: string, statType: 'hp' | 'mp' | 'sp', newValue: number) => {
    handleUpdateCharacter(characterId, {
      [statType]: newValue
    });
  };

  return (
    <div className="">
      {/* Header with Add Character Button */}
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-bold">Party Management</h2>
        <button
          onClick={() => {
            setSelectedCharacterId(null);
            setShowEditor(true);
          }}
          className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors"
        >
          Add Character
        </button>
      </div>

      {/* Character List with Stat Gauges */}
      <CharacterList
        party={gameState.party}
        onSelectCharacter={(id) => {
          setSelectedCharacterId(id);
          setShowEditor(true);
        }}
        onStatChange={handleStatChange}
      />

      {/* Character Editor Modal */}
      {showEditor && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold">
                {selectedCharacter ? 'Edit Character' : 'Create Character'}
              </h3>
            </div>
            
            <CharacterEditor
              character={selectedCharacter}
              onSave={handleAddCharacter}
              onUpdate={handleUpdateCharacter}
              onDelete={handleDeleteCharacter}
              onClose={() => {
                setShowEditor(false);
                setSelectedCharacterId(null);
              }}
              isRoomCreator={true}
            />
          </div>
        </div>
      )}

      {/* Empty State */}
      {gameState.party.length === 0 && !showEditor && (
        <div className="text-center py-8 text-gray-500">
          <p>No characters in the party yet.</p>
          <p>Click "Add Character" to create one!</p>
        </div>
      )}
    </div>
  );
}